const GOAL_MIN = 1;
const GOAL_MAX = 7;
/* Gong smie zaznieť len za dokončenie, ktoré appka naozaj videla naživo.
   Bežiaci odpočet sa kontroluje každých 250 ms, takže 2 s tolerancia nepotlačí
   skutočné dokončenie – len oneskorený callback po návrate z pozadia. */
const TIMER_SOUND_GRACE_MS = 2000;

/* ---------- Stav aplikácie ---------- */

let state = null;
let activeTab = 'dnes';
let selectedPlan = 'push';
let durationInterval = null; // jediný interval pre zobrazenie trvania tréningu
let sessionNoteKey = null;   // práve zobrazená poznámka k aktívnej session (kľúč prekladu)
let sessionNoteTimer = null; // skrytie dočasnej poznámky
let lastXP = 0;
let lastUnlocked = [];
let lastLevelUp = 0;          // nová úroveň po poslednom tréningu/aktivite (0 = bez zmeny)
let lastAchXP = 0;           // XP získané z úspechov po poslednom tréningu
let lastWorkoutId = null;    // id posledného dokončeného tréningu (pre Undo)
let editingPlan = null;      // id plánu v editačnom móde
let newPlanId = null;        // id práve vytvoreného plánu (zrušenie ho zahodí); neukladá sa
let editDraft = null;        // kópia cvikov počas editácie
/* Režim úprav plánov: prepínač pod selektorom. Zámerne sa NEukladá –
   aplikácia vždy otvorí čistý výber plánu. */
let planManageMode = false;
let pendingImport = null;    // naimportované dáta čakajúce na potvrdenie
let pendingDeleteWorkout = null; // id tréningu čakajúceho na vymazanie
let timerInterval = null;
let timerEnd = 0;
/* Každé spustenie odpočtu má vlastné id. Dokončenie sa viaže na konkrétne id,
   takže starý odpočet sa nikdy nemôže "dokončiť" dvakrát ani po návrate z pozadia. */
let timerSessionId = 0;
let timerCompletedId = 0;      // id odpočtu, ktorého dokončenie už bolo spracované
let timerHiddenAt = 0;         // kedy sa stránka skryla (0 = je viditeľná)
let timerPausedLeft = null;    // zostávajúce ms pozastaveného odpočtu (null = beží)
let timerTotalMs = 0;          // celý čas spusteného odpočtu (pre Znova a ukazovateľ)
let timerPresetId = null;      // predvoľba, z ktorej odpočet beží (null = vlastný čas)
let restNoteTimer = null;      // skrytie hlášky "Nahradené …"
let dayWatchInterval = null;   // jediný interval pre zmenu dňa (nikdy sa neduplikuje)
let lastRenderedDay = null;    // naposledy vykreslený lokálny deň "YYYY-MM-DD"
/* Stav kalendára – len v pamäti, zámerne sa neukladá (kalendár sa vždy otvára na aktuálnom mesiaci). */
let viewYear = new Date().getFullYear();
let viewMonth = new Date().getMonth();
let selectedDayKey = null;

/* ---------- Pomocné funkcie ---------- */

/* Lokálny kľúč dňa "YYYY-MM-DD". Zámerne z lokálnych zložiek – toISOString() je UTC
   a mohol by posunúť dátum o deň. */
function localDateKey(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function todayISO() {
  return localDateKey(new Date());
}

function parseDate(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

/* ISO rok + týždeň (pondelok = 1. deň), napr. "2026-W34" */
function weekKey(date) {
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const dayNum = (d.getDay() + 6) % 7; // pondelok = 0
  d.setDate(d.getDate() - dayNum + 3);
  const firstThursday = new Date(d.getFullYear(), 0, 4);
  const firstDayNum = (firstThursday.getDay() + 6) % 7;
  firstThursday.setDate(firstThursday.getDate() - firstDayNum + 3);
  const week = 1 + Math.round((d - firstThursday) / (7 * 24 * 3600 * 1000));
  return `${d.getFullYear()}-W${String(week).padStart(2, '0')}`;
}

function prevWeekKey(key) {
  const [year, week] = key.split('-W').map(Number);
  const firstDay = new Date(year, 0, 4);
  const dayNum = (firstDay.getDay() + 6) % 7;
  firstDay.setDate(firstDay.getDate() - dayNum + 3);
  firstDay.setDate(firstDay.getDate() + (week - 1) * 7);
  return weekKey(addDays(firstDay, -7));
}

function currentWeekKey() {
  return weekKey(new Date());
}

function monthKey(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

function currentMonthKey() {
  return monthKey(new Date());
}

function uid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

/* ---------- Dátumy pre ukážkové dáta ---------- */

function sampleDates() {
  const dates = [];
  const cur = parseDate(todayISO());
  const curWeek = weekKey(cur);
  // späť, kým nenájdeme pondelok predchádzajúceho týždňa
  let mon = new Date(cur);
  while (weekKey(mon) === curWeek) mon = addDays(mon, -1);
  while (weekKey(addDays(mon, -1)) === weekKey(mon)) mon = addDays(mon, -1);
  dates.push(mon, addDays(mon, 2), addDays(mon, 4)); // pondelok, streda, piatok
  return dates;
}

/* ---------- Ukážkové dáta (len prvý štart) ---------- */

function buildSampleHistory() {
  const dates = sampleDates();
  const order = activePlanIds().slice(0, 3);
  const weights = {
    'Bench press': 40, 'Tlaky nad hlavou': 25, 'Upažovanie': 8,
    'Príťahy v predklone': 40, 'Veslovanie na kladke': 35, 'Bicepsové zdvihy': 12,
    'Drepy': 50, 'Leg press': 80, 'Výpady': 10, 'Zakopávanie': 25, 'Lýtka': 40,
  };
  const history = [];
  order.forEach((planId, i) => {
    const plan = getPlan(planId);
    if (!plan) return;
    const exercises = plan.exercises.map(ex => ({
      name: ex.name,
      exId: (ex.id && BUILTIN_EXERCISE_IDS.has(ex.id)) ? ex.id : undefined,
      sets: ex.sets,
      reps: ex.reps,
      weight: weights[ex.name] !== undefined ? weights[ex.name] : ex.weight,
    }));
    history.push({
      id: uid(),
      planId: plan.id,
      planName: recordedPlanName(plan),
      date: dates[i].toISOString().slice(0, 10),
      xp: workoutXpFor(exercises.reduce((sum, e) => sum + e.sets, 0)),
      note: '',
      exercises: exercises.map(e => Object.assign({}, e, { setsDone: e.sets })),
    });
  });
  return history;
}

/* ---------- Načítanie / ukladanie stavu / migrácia ---------- */

/* Normalizuje minúty/sekundy vlastného času pauzy. Sekundy >= 60 sa prenesú do minút,
   hodnoty sa orežú na 0..60 min / 0..59 s. Čisto aritmetická – nevkladá žiadny default. */
function normalizeCustomRest(min, sec) {
  let m = Math.floor(Number(min));
  let s = Math.floor(Number(sec));
  if (!Number.isFinite(m) || m < 0) m = 0;
  if (!Number.isFinite(s) || s < 0) s = 0;
  m += Math.floor(s / 60);
  s = s % 60;
  if (m > 60) { m = 60; s = 0; }
  return { minutes: m, seconds: s };
}

/* ---------- Predvoľby časovača oddychu ----------
   Usporiadaný zoznam s stabilnými id. Poradie poľa JE poradie tlačidiel.
   `seconds` je celé číslo, `name` je voliteľný VLASTNÝ názov – prázdny znamená
   "odvoď popis z času a prelož ho". Vlastný názov sa nikdy neprekladá. */

const REST_PRESET_MIN_SECONDS = 1;
const REST_PRESET_MAX_SECONDS = 3600;   // rovnaký strop ako normalizeCustomRest (60 min)
const REST_PRESET_NAME_MAX = 40;

/* Pôvodné tri predvoľby, ktoré boli doteraz natvrdo v HTML: 60 s, 90 s, 120 s. */
function defaultRestPresets() {
  return [60, 90, 120].map((seconds) => ({ id: 'rest_preset_' + uid(), seconds, name: '' }));
}

/* NEDEŠTRUKTÍVNA normalizácia: platná položka zostáva presne taká, aká bola
   (id, názov, poradie), poškodená sa zahodí. Duplicitné id dostane nové.
   Prázdne pole vráti prázdne pole – zmazané predvoľby sa NIKDY nevracajú. */
function cleanRestPresets(raw) {
  if (!Array.isArray(raw)) return null;
  const out = [];
  const ids = new Set();
  for (const item of raw) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) continue;
    const seconds = Math.round(Number(item.seconds));
    if (!Number.isFinite(seconds) || seconds < REST_PRESET_MIN_SECONDS || seconds > REST_PRESET_MAX_SECONDS) continue;
    let id = typeof item.id === 'string' && item.id ? item.id : '';
    if (!id || ids.has(id)) id = 'rest_preset_' + uid();
    ids.add(id);
    const name = typeof item.name === 'string' ? item.name.trim().slice(0, REST_PRESET_NAME_MAX) : '';
    out.push({ id, seconds, name });
  }
  return out;
}

function restPresets() {
  const list = state && state.settings ? state.settings.restPresets : null;
  return Array.isArray(list) ? list : [];
}

function restPresetById(id) {
  return restPresets().find((p) => p.id === id) || null;
}

/* Popis predvoľby: vlastný názov sa NIKDY neprekladá, odvodený sa prekladá vždy. */
function restPresetLabel(preset) {
  if (!preset) return '';
  return preset.name ? preset.name : t('rest.secondsLabel', { n: preset.seconds });
}

/* Presný čas predvoľby ako M:SS – používa sa pri správe, aby bol čas vidieť aj vtedy,
   keď má predvoľba vlastný názov. */
function formatPresetTime(seconds) {
  const n = Math.max(0, Math.round(Number(seconds) || 0));
  return Math.floor(n / 60) + ':' + String(n % 60).padStart(2, '0');
}

/* Spoločná validácia pre "Uložiť predvoľbu" aj pre úpravu/pridanie v správe.
   Vráti { seconds, name } alebo { error, clash }. */
function validatePresetValues(minutes, seconds, name, excludeId) {
  const rawM = Number(minutes);
  const rawS = Number(seconds);
  if (!Number.isInteger(rawM) || !Number.isInteger(rawS) || rawM < 0 || rawS < 0) return { error: 'invalid' };
  /* Strop sa kontroluje na SUROVÝCH hodnotách – normalizeCustomRest by ich inak ticho
     ore zal na 60 minút a používateľ by dostal iný čas, než zadal. */
  if (rawM * 60 + rawS > REST_PRESET_MAX_SECONDS) return { error: 'tooLong' };
  const norm = normalizeCustomRest(rawM, rawS);
  const total = norm.minutes * 60 + norm.seconds;
  if (!Number.isFinite(total) || total < REST_PRESET_MIN_SECONDS) return { error: 'zero' };
  const clean = String(name == null ? '' : name).trim();
  if (clean.length > REST_PRESET_NAME_MAX) return { error: 'name' };
  /* Rovnaký čas je povolený IBA vtedy, keď majú obe predvoľby vlastné a rozdielne názvy –
     inak by dve tlačidlá vyzerali úplne rovnako. */
  const clash = restPresets().find((p) => p.seconds === total && p.id !== excludeId);
  if (clash && !(clean && clash.name && clean.toLowerCase() !== clash.name.toLowerCase())) {
    return { error: 'duplicate', clash };
  }
  return { seconds: total, name: clean };
}

function presetErrorMessage(result) {
  if (result.error === 'zero') return t('rest.errZero');
  if (result.error === 'tooLong') return t('rest.errTooLong');
  if (result.error === 'name') return t('rest.errName');
  if (result.error === 'duplicate') return t('rest.errDuplicate', { name: restPresetLabel(result.clash) });
  return t('rest.errInvalid');
}

/* Uloží vlastný čas do panela (predvyplnenie nabudúce). Existujúce správanie. */
function rememberCustomTime(minutes, seconds) {
  state.settings.customRestMinutes = minutes;
  state.settings.customRestSeconds = seconds;
  saveState();
}

function addRestPreset(seconds, name) {
  const list = restPresets().slice();
  const preset = { id: 'rest_preset_' + uid(), seconds, name: name || '' };
  list.push(preset);
  state.settings.restPresets = list;
  saveState();
  return preset;
}

function updateRestPreset(id, seconds, name) {
  state.settings.restPresets = restPresets().map((p) => (
    p.id === id ? { id, seconds, name: name || '' } : p
  ));
  saveState();
}

function deleteRestPreset(id) {
  state.settings.restPresets = restPresets().filter((p) => p.id !== id);
  saveState();
}

function moveRestPreset(id, delta) {
  const list = restPresets().slice();
  const at = list.findIndex((p) => p.id === id);
  const to = at + delta;
  if (at < 0 || to < 0 || to >= list.length) return;   // okraje sa neobtáčajú
  const [item] = list.splice(at, 1);
  list.splice(to, 0, item);
  state.settings.restPresets = list;
  saveState();
}

